    command
        .env("HOME", home)
        .env("PATH", path)
        .env("CALLISTO_TEST_LOG", publishers.log)
        .env("CALLISTO_TEST_GIT_TRACE", publishers.git_trace)
        .env("CALLISTO_TEST_FORGE_MARKER", publishers.forge_marker)
