#[non_exhaustive]
pub enum ReleaseInclusionReason {
    Changeset,
    Inference,
    ExplicitSelection,
    LinkedGroup {
        group_id: String,
    },
    FixedGroup {
        group_id: String,
    },
    Cascade {
