    let path = format!("{}:{}", publishers.bin.display(), std::env::var("PATH").unwrap());
    let mut command = Command::new(env!("CARGO_BIN_EXE_callisto"));
    command.args(["--cwd", root.to_str().unwrap()]).args(args);
